import * as THREE from 'three/webgpu';
import { texture, mul, add, sin } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(3.2, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Load texture
  const imageTexture = ctx.textureLoader.load(config.assets.imageUrl);

  // Create plane: source rect 512x320, aspect ratio 1.6:1
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);

  // TSL material with subtle grain overlay
  const uv = new THREE.uv();

  // Procedural grain using sin-based pattern
  const grain = mul(
    sin(mul(uv.x, 80.0) + mul(uv.y, 80.0)),
    0.02
  );

  // Apply grain to base texture
  const baseColor = texture(imageTexture);
  const grainedColor = mul(baseColor, add(1.0, grain));

  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: grainedColor,
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    imageTexture.dispose();
    gsap.killTweensOf(group);
  };

  group.userData.handlers = {};

  return group;
}
